(()=>{
const esc=escapeHTML;
const entry=document.createElement('button');entry.className='barcode-entry';entry.innerHTML='<span class="barcode-symbol" aria-hidden="true">▥</span><span><strong>바코드로 제품 찾기</strong><small>공개 DB의 제품 사진 · 원재료 · 영양표</small></span><span aria-hidden="true">↗</span>';document.querySelector('.photo-entry').before(entry);
const modal=document.createElement('dialog');modal.className='barcode-dialog';modal.id='barcode-dialog';modal.setAttribute('aria-labelledby','barcode-title');modal.innerHTML=`<div class="modal-top"><span class="eyebrow">SCAN · CHECK · UNDERSTAND</span><button class="icon-button" id="barcode-close" aria-label="바코드 조회 닫기">×</button></div><h2 id="barcode-title">바코드에서 시작해요</h2><p>포장지 바코드를 입력하거나, 지원되는 기기에서 카메라로 읽어보세요.</p><form id="barcode-form"><label for="barcode-input">바코드 숫자</label><div class="barcode-input-row"><input id="barcode-input" inputmode="numeric" autocomplete="off" maxlength="24" placeholder="8·12·13·14자리" required><button class="primary-button" id="barcode-submit">조회하기</button></div></form><div class="barcode-camera-actions"><button class="secondary-button" id="barcode-camera">카메라로 스캔</button><button class="secondary-button" id="barcode-stop" hidden>카메라 중지</button></div><p class="minor-note" id="barcode-support">카메라는 바코드 인식을 지원하는 브라우저에서 사용할 수 있어요. 숫자 입력은 모든 브라우저에서 가능해요.</p><video id="barcode-video" playsinline muted hidden aria-label="바코드 카메라 미리보기"></video><p class="barcode-status" id="barcode-status" role="status" aria-live="polite"></p><div id="barcode-result"></div><div class="barcode-footer"><p>바코드 숫자는 Open Food Facts로 전송해 조회해요. 카메라 영상은 전송하거나 저장하지 않아요. 사용자 참여 자료로 국내 제품이 없거나 정보가 오래되었을 수 있어요.</p><a href="https://world.openfoodfacts.org/" target="_blank" rel="noopener noreferrer">제품 자료 © Open Food Facts 기여자</a> · <a href="https://opendatacommons.org/licenses/odbl/1-0/" target="_blank" rel="noopener noreferrer">데이터 ODbL</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">사진 CC BY-SA 3.0</a></div>`;
document.body.append(modal);const q=s=>modal.querySelector(s),status=m=>q('#barcode-status').textContent=m;let stream=null,timer=null,cameraRun=0,requestRun=0,controller=null;const cache=new Map();let requests=[];
entry.onclick=()=>{modal.showModal();modal.scrollTop=0;q('#barcode-input').focus()};q('#barcode-close').onclick=()=>modal.close();
function stopCamera(){cameraRun++;clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop());stream=null;q('#barcode-video').srcObject=null;q('#barcode-video').hidden=true;q('#barcode-stop').hidden=true;q('#barcode-camera').disabled=false}
modal.addEventListener('close',()=>{stopCamera();requestRun++;controller?.abort();controller=null;q('#barcode-submit').disabled=false;entry.focus()});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopCamera()});q('#barcode-stop').onclick=()=>{stopCamera();status('카메라를 중지했어요. 바코드 숫자를 입력할 수도 있어요.')};
function render(p){const link='https://world.openfoodfacts.org/product/'+p.code;const allergens=p.allergens.length?p.allergens.map(esc).join(' · '):'자료 미제공';q('#barcode-result').innerHTML=`<article class="barcode-product"><div class="barcode-product-head">${p.image?`<img class="barcode-product-image" src="${esc(p.image)}" alt="${esc(p.name)} · Open Food Facts 등록 사진" referrerpolicy="no-referrer">`:'<div class="barcode-no-image">사진 미등록</div>'}<div><span class="badge record">외부 공개 DB · 포장지 대조 필요</span><h3>${esc(p.name)}</h3><p>${esc(p.brand)}</p><small>바코드 ${p.code}</small><a href="${link}" target="_blank" rel="noopener noreferrer">제품 원본 · 사진 출처 ↗</a></div></div><p class="barcode-data-note">식약처 신고자료와 동일 제품으로 검증한 결과가 아니에요. 현재 포장지의 이름·제조사·성분과 비교해 주세요.${p.modified?' 외부 자료 수정일 '+new Date(p.modified*1000).toLocaleDateString('ko-KR')+'.':''}</p><h4>영양표에 기록된 값</h4><p class="minor-note">100g 또는 100mL 기준 · 외부 DB 원문 값 · 섭취 권장량이 아니에요.</p><div class="nutrition-grid">${p.nutrients.map(n=>`<div><small>${n.label}</small><strong>${n.value===null?'미제공':Number(n.value.toFixed(2)).toLocaleString('ko-KR')+' <small>'+n.unit+'</small>'}</strong></div>`).join('')}</div><details class="barcode-raw"><summary>외부 DB의 알레르기·첨가물 코드</summary><p>알레르기 표기: ${allergens}</p><p>첨가물 코드: ${p.additives.length?p.additives.map(esc).join(' · '):'자료 미제공'}</p><small>외부 DB의 기록이며, 목록이 비어 있어도 무첨가·알레르기 없음으로 판정하지 않아요.</small></details><label class="photo-field">포장지와 비교할 원재료 표시<textarea id="barcode-ingredients" rows="5" maxlength="20000">${esc(p.ingredients)}</textarea></label><p class="minor-note">${p.korean?'한글 원재료 자료가 있어요.':'한글 자료가 없을 수 있어요. 포장지의 한글 원재료 표시로 수정하거나 사진 문자 인식을 이용해 주세요.'} 현재 설명 사전은 한글 명칭 5종을 대조해요.</p><label class="confirm-label"><input id="barcode-confirm" type="checkbox">현재 포장지와 원재료 문구를 비교했어요.</label><div id="barcode-analysis" aria-live="polite"></div><button class="secondary-button" id="barcode-ocr">포장지 사진·직접 입력으로 확인</button></article>`;
 const img=q('.barcode-product-image');if(img)img.onerror=()=>{img.replaceWith(Object.assign(document.createElement('p'),{textContent:'사진을 불러오지 못했어요. 원본 출처에서 확인해 주세요.'}))};
 const update=()=>{q('#barcode-analysis').innerHTML=q('#barcode-confirm').checked?(/[가-힣]/.test(q('#barcode-ingredients').value)?AdditiveNote.panel(AdditiveNote.fromText(q('#barcode-ingredients').value),'외부 DB 문구 · 사용자 포장지 대조 기준'):'<p class="barcode-data-note">한글 성분명이 없어 현재 사전으로 대조할 수 없어요. 한글 원재료 표시를 입력해 주세요.</p>'):''};q('#barcode-confirm').onchange=update;q('#barcode-ingredients').oninput=()=>{q('#barcode-confirm').checked=false;update()};q('#barcode-ocr').onclick=()=>{modal.close();document.querySelector('.photo-entry').click()};
}
async function lookup(raw){const code=BarcodeData.normalize(raw);if(!BarcodeData.valid(code)){status('바코드 자릿수와 마지막 검증 숫자를 확인해 주세요. 숫자를 임의로 보정하지 않아요.');return}stopCamera();controller?.abort();const run=++requestRun;q('#barcode-result').innerHTML='';q('#barcode-submit').disabled=true;status('공개 제품 DB에서 조회하고 있어요…');try{let p=cache.get(code);if(!p){const now=Date.now();requests=requests.filter(t=>now-t<60000);if(requests.length>=10)throw new Error('rate');requests.push(now);const currentController=new AbortController();controller=currentController;const timeout=setTimeout(()=>currentController.abort(),15000);let response;try{response=await fetch(BarcodeData.url(code),{signal:currentController.signal,credentials:'omit',referrerPolicy:'no-referrer'});}finally{clearTimeout(timeout)}if(run!==requestRun||!modal.open)return;if(response.status===404){status('이 바코드는 공개 DB에서 찾지 못했어요. 아래의 포장지 사진 읽기를 이용해 주세요.');fallback();return}if(response.status===429)throw new Error('rate');if(!response.ok)throw new Error('network');p=BarcodeData.unpack(await response.json(),code);if(!p){status('등록된 제품 정보가 없어요. 포장지 사진으로 확인해 주세요.');fallback();return}cache.set(code,p)}if(run!==requestRun||!modal.open)return;render(p);status('제품 자료를 찾았어요. 포장지와 같은 제품인지 확인해 주세요.')}catch(e){if(run!==requestRun||!modal.open)return;status(e.message==='rate'?'조회가 많아 잠시 쉬어야 해요. 1분 후 다시 시도해 주세요.':'공개 DB에 연결하지 못했어요. 잠시 후 다시 조회하거나 포장지 사진으로 확인해 주세요.');fallback()}finally{if(run===requestRun)q('#barcode-submit').disabled=false}}
function fallback(){q('#barcode-result').innerHTML='<button class="secondary-button" id="barcode-fallback">포장지 사진·직접 입력으로 확인</button>';q('#barcode-fallback').onclick=()=>{modal.close();document.querySelector('.photo-entry').click()}}
q('#barcode-form').onsubmit=e=>{e.preventDefault();lookup(q('#barcode-input').value)};
q('#barcode-camera').onclick=async()=>{if(!('BarcodeDetector'in window)||!navigator.mediaDevices?.getUserMedia){status('이 브라우저는 카메라 바코드 인식을 지원하지 않아요. 바코드 숫자를 입력해 주세요.');return}stopCamera();const run=cameraRun;try{const formats=(await BarcodeDetector.getSupportedFormats()).filter(f=>['ean_13','ean_8','upc_a','upc_e','itf'].includes(f));if(!formats.length)throw new Error('formats');const detector=new BarcodeDetector({formats});q('#barcode-camera').disabled=true;status('카메라 사용을 허용한 뒤 바코드를 비춰 주세요.');const acquired=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(run!==cameraRun||!modal.open){acquired.getTracks().forEach(t=>t.stop());return}stream=acquired;const video=q('#barcode-video');video.srcObject=stream;video.hidden=false;q('#barcode-stop').hidden=false;await video.play();const deadline=Date.now()+30000;const scan=async()=>{if(run!==cameraRun)return;try{const codes=await detector.detect(video);if(run!==cameraRun)return;const match=codes.find(c=>BarcodeData.valid(c.rawValue));if(match){q('#barcode-input').value=BarcodeData.normalize(match.rawValue);lookup(match.rawValue);return}}catch{}if(Date.now()>deadline){stopCamera();status('바코드를 읽지 못했어요. 숫자를 직접 입력해 주세요.');return}timer=setTimeout(scan,400)};scan()}catch(e){if(run!==cameraRun)return;stopCamera();status(e.name==='NotAllowedError'?'카메라 권한이 없어 열지 못했어요. 바코드 숫자로 조회할 수 있어요.':'카메라 인식을 시작하지 못했어요. 바코드 숫자로 조회해 주세요.')}};
const dictionaryEntry=document.createElement('button');dictionaryEntry.className='nav-item';dictionaryEntry.textContent='첨가물 사전';document.querySelector('#guide-nav').before(dictionaryEntry);
const dictionary=document.createElement('dialog');dictionary.className='barcode-dialog';dictionary.setAttribute('aria-labelledby','dictionary-title');dictionary.innerHTML=`<div class="modal-top"><span class="eyebrow">KNOW YOUR INGREDIENTS</span><button class="icon-button" aria-label="첨가물 사전 닫기">×</button></div><h2 id="dictionary-title">첨가물이 하는 일</h2><p>현재 등록 제품에서 찾은 5종의 첨가물을 공식 자료와 대조했어요. 일반적인 용도이며 제품별 실제 사용 목적과 첨가량을 뜻하지 않아요.</p><div class="dictionary-list">${AdditiveNote.entries.map(e=>`<details class="additive-item"><summary>${esc(e.name)} <span>${esc(AdditiveNote.purposeLabel(e))}</span></summary>${AdditiveNote.explanation(e)}</details>`).join('')}</div><p class="minor-note">식약처 공전 근거 사전 · 실시간 식약처 API 연동은 아직 없어요. 전체 첨가물 목록이나 건강 점수가 아닙니다.</p>`;document.body.append(dictionary);dictionaryEntry.onclick=()=>{dictionary.showModal();dictionary.scrollTop=0};dictionary.querySelector('button').onclick=()=>dictionary.close();dictionary.addEventListener('close',()=>dictionaryEntry.focus());
})();
